#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // sum 一定要初始化为 0。局部变量不初始化时里面是内存里的随机值，
    // 在随机数上做累加，输出会是一堆垃圾数据，而且时对时错。
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += i;
    }

    cout << sum << endl;
    return 0;
}

