#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 累乘要从 1 开始！初值写 0 的话乘什么都还是 0。
    // 0! 按定义等于 1，这个初值正好也对上。
    long long fact = 1;

    int i = 1;
    while (i <= n) {
        fact *= i;
        i++;          // 漏掉这一句就是死循环：i 永远是 1
    }

    // 20! = 2432902008176640000，远超 int 的范围（约 21 亿），
    // 所以用 long long 存；C++ 的 cout 按变量类型输出，不用记 %lld。
    cout << fact << endl;
    return 0;
}

