#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // do-while 先执行一次循环体，再判断条件。
    // 换成 while (n > 0) 的话，n = 0 时一次都不执行，位数是 0；
    // 而 0 本身是 1 位数。
    int count = 0;
    do {
        count++;
        n /= 10;          // 整数除法：123 / 10 得到 12，正好抹掉最后一位
    } while (n > 0);      // 结尾这个分号不能少

    cout << count << endl;
    return 0;
}

