#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    // vector 是 C++ 的可变长数组：长度可以在运行时决定。
    // vector<int> v(n) 创建了 n 个 int，下标范围还是 0 ~ n-1。
    vector<int> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i];
    }

    int count = 0;
    int sum = 0;

    // 范围 for：把 v 里的元素一个一个取出来放进 x。
    // 不用维护下标，也就不会写出越界的 v[n]。
    for (int x : v) {
        if (x <= 0) {
            continue;     // 非正数：跳过本轮剩下的语句，直接看下一个元素
        }
        count++;
        sum += x;
    }

    // n = 0 时 v 是空容器，范围 for 一圈都不转，输出 0 0。
    cout << count << " " << sum << endl;
    return 0;
}

