#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 0 和 1 都不是素数，先单独处理掉，
    // 否则下面的循环一次试除都不会做，很容易被漏判成 yes。
    bool is_prime = true;
    if (n < 2) {
        is_prime = false;
    }

    // 只需要试除到根号 n：如果 n 有一个大于根号 n 的因子，
    // 就必然还有一个小于根号 n 的因子，早该被试出来了。
    // i * i <= n 比调 sqrt() 更省事，也不用引 <cmath>。
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            is_prime = false;
            break;        // 已经确定不是素数，再试下去没有意义
        }
    }

    // 注意：bool 变量直接输出只会得到 1 / 0，这里要的是 yes / no，
    // 所以用三目运算符自己挑字符串。
    cout << (is_prime ? "yes" : "no") << endl;
    return 0;
}

