#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 外层走一步 = 印一行，内层走一圈 = 把这一行的星号印完
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            cout << "*";     // 只印星号，不印空格
        }
        // 换行必须写在内层循环结束之后、外层循环里面。
        // 写进内层循环就会变成每颗星单独占一行。
        cout << endl;
    }
    return 0;
}

